mapper.select:
select t.rel_id,t.rel_id relId,t.ad_id,t.ad_id adId,t.machine_id,t.machine_id
machineId,t.machine_code,t.machine_code machineCode,t.remark,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.machine_name,t.machine_name machineName
from access_control_ad_rel t
where 1 =1

    and t.rel_id= #{relId}


    and t.ad_id= #{adId}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}

order by t.create_time desc

    limit #{page}, #{row}

